package com.yeyamo_mobile.api.graph_service.infrastructure;
import com.fasterxml.jackson.databind.*;import org.slf4j.MDC;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;
@Component public class GraphEventConsumer{private final ObjectMapper json;private final GraphProjectionService projection;public GraphEventConsumer(ObjectMapper j,GraphProjectionService p){json=j;projection=p;}@KafkaListener(topics={"${yeyamo.kafka.topics.culture-events:culture.events}","${yeyamo.kafka.topics.catalog-events:catalog.events}","${yeyamo.kafka.topics.partner-events:partner-events}","${yeyamo.kafka.topics.place-events:place.events}","${yeyamo.kafka.topics.event-events:event.events}"},groupId="${spring.kafka.consumer.group-id:graph-service}")public void consume(String raw)throws Exception{JsonNode event=json.readTree(raw);if(event.path("eventVersion").asInt()!=1)throw new IllegalArgumentException("Unsupported event version");MDC.put("correlationId",event.path("correlationId").asText(event.path("eventId").asText()));try{projection.apply(event);}finally{MDC.remove("correlationId");}}}
